// Section D4 obstacles (PURE data): what people and machines must walk round between the crater and the van — the
// set's rubble chunks near the fight (world/set.tsx seeds rch_/sch_; centres and radii measured from the set), the
// van, the burnt car on the avenue, the big leaning slab south of the van, D1's wrecks — and avoid(), which bends a
// path round them (as D1's lanes do round the crater's clutter).
import {lerp} from '../../../kit/math';
import type {XZ} from './motion';

