/** rotated boxes: centre, heading (deg), half-length along the heading, half-width */
export const BOXES: {x: number; z: number; h: number; hl: number; hw: number; key: string}[] = [
  {x: 8.3, z: 1.15, h: 120, hl: 3.05, hw: 1.05, key: 'van'},
  {x: 31, z: 6, h: 60, hl: 2.2, hw: 0.9, key: 'car'},
  {x: 8.73, z: 8.68, h: 62.9, hl: 2.2, hw: 0.75, key: 'leaning slab (rslab_15)'},
  {x: 6.6, z: 3.2, h: 30, hl: 1.15, hw: 0.4, key: 'death slab'},
];
/** D1's wrecks lying west of the crater rim (approx. footprints as circles) */
export const WRECKS_D1: {x: number; z: number; r: number}[] = [{x: 39.6, z: 4.35, r: 1.2}, {x: 40.6, z: -3.6, r: 1.1}, {x: 40.7, z: -4.9, r: 1.0}];

const boxDist = (b: (typeof BOXES)[number], x: number, z: number) => {
  const h = (b.h * Math.PI) / 180, f = {x: Math.sin(h), z: -Math.cos(h)}, r = {x: Math.cos(h), z: Math.sin(h)};
  const a = (x - b.x) * f.x + (z - b.z) * f.z, s = (x - b.x) * r.x + (z - b.z) * r.z;
  const da = Math.abs(a) - b.hl, ds = Math.abs(s) - b.hw;
  return {d: Math.max(da, ds), a, s, f, r};
};
/** push a point out of every obstacle by `clear` metres */
export const pushOut = (p: XZ, clear: number): XZ => {
  let q = {...p};
  for (let it = 0; it < 3; it++) {
    for (const o of [...CHUNKS, ...WRECKS_D1]) {
      const dx = q.x - o.x, dz = q.z - o.z, d = Math.hypot(dx, dz) || 1e-3;
      if (d < o.r + clear) q = {x: o.x + (dx / d) * (o.r + clear), z: o.z + (dz / d) * (o.r + clear)};
    }
    for (const b of BOXES) {
      const k = boxDist(b, q.x, q.z);
      if (k.d < clear) {
        // out through the nearer side
        const da = b.hl + clear - Math.abs(k.a), ds = b.hw + clear - Math.abs(k.s);
        if (ds < da) q = {x: q.x + k.r.x * Math.sign(k.s || 1) * ds, z: q.z + k.r.z * Math.sign(k.s || 1) * ds};
        else q = {x: q.x + k.f.x * Math.sign(k.a || 1) * da, z: q.z + k.f.z * Math.sign(k.a || 1) * da};
      }
    }
  }
  return q;
};
/** resample a path every 0.7 m and bend it round the obstacles (keeps the first point and the last `keep` metres) */
export const avoid = (pts: XZ[], clear = 0.5, keep = 2.6): XZ[] => {
  const total = pts.slice(1).reduce((s, b, i) => s + Math.hypot(b.x - pts[i].x, b.z - pts[i].z), 0);
  const out: XZ[] = [pts[0]];
  let acc = 0;
  pts.slice(1).forEach((b, i) => {
    const a = pts[i], L = Math.hypot(b.x - a.x, b.z - a.z), n = Math.max(1, Math.ceil(L / 0.7));
    for (let k = 1; k <= n; k++) {
      const u = k / n, p = {x: lerp(a.x, b.x, u), z: lerp(a.z, b.z, u)};
      out.push(total - (acc + L * u) > keep ? pushOut(p, clear) : p);
    }
    acc += L;
  });
  // relax twice so the bends are smooth (the ends stay)
  let r = out;
  for (let it = 0; it < 2; it++) r = r.map((p, i) => (i === 0 || i >= r.length - 4 ? p : {x: (r[i - 1].x + p.x * 2 + r[i + 1].x) / 4, z: (r[i - 1].z + p.z * 2 + r[i + 1].z) / 4}));
  return r;
};
/** how far a point is inside any obstacle (> 0 = inside), for checks */
export const intrusion = (p: XZ, rad: number): {d: number; what: string} => {
  let worst = {d: -1e9, what: ''};
  for (const o of CHUNKS) { const d = o.r + rad - Math.hypot(p.x - o.x, p.z - o.z); if (d > worst.d) worst = {d, what: `chunk(${o.x},${o.z})`}; }
  for (const b of BOXES) { const d = rad - boxDist(b, p.x, p.z).d; if (d > worst.d) worst = {d, what: b.key}; }
  return worst;
};
